css:
.ln-root{position:absolute;left:64px;bottom:72px;display:flex;align-items:flex-end;font-family:var(--ln-font);}
.ln-avatar{width:var(--ln-avatar-size);height:var(--ln-avatar-size);border-radius:var(--ln-radius);overflow:hidden;background:linear-gradient(160deg,#071018,#160a1a);box-shadow:0 0 0 2px var(--ln-cyan),0 0 30px rgba(34,211,238,.5);display:flex;align-items:center;justify-content:center;flex:0 0 auto;}
.ln-avatar img{width:100%;height:100%;object-fit:cover;display:none;}
.ln-avatar img.is-ready{display:block;}
.ln-fallback{color:rgba(255,255,255,.35);font-size:40px;font-weight:800;line-height:1;}
.ln-avatar:has(img.is-ready) .ln-fallback{display:none;}
.ln-panel{position:relative;overflow:hidden;background:linear-gradient(100deg,rgba(6,8,16,.94),rgba(10,6,20,.82));border-radius:var(--ln-radius);padding:18px 56px 18px 24px;min-width:340px;box-shadow:0 0 34px rgba(34,211,238,.18),inset 0 0 30px rgba(244,114,182,.07);}
.ln-edge{position:absolute;left:0;top:0;bottom:0;width:4px;background:linear-gradient(180deg,var(--ln-cyan),var(--ln-magenta));box-shadow:0 0 18px var(--ln-cyan);}
.ln-text{position:relative;z-index:2;}
.ln-team{display:flex;align-items:center;gap:10px;margin-bottom:6px;}
.ln-team:not(:has(.ln-team-name:not(:empty),img.is-ready)){display:none;}
.ln-team-logo{position:relative;width:var(--ln-team-logo);height:var(--ln-team-logo);flex:0 0 auto;display:flex;align-items:center;justify-content:center;}
.ln-team-logo img{width:100%;height:100%;object-fit:contain;display:none;}
.ln-team-logo img.is-ready{display:block;}
.ln-team-fallback{width:8px;height:8px;border-radius:50%;background:var(--ln-magenta);box-shadow:0 0 10px var(--ln-magenta);}
.ln-team-logo:has(img.is-ready) .ln-team-fallback{display:none;}
.ln-team-name{color:var(--ln-magenta);font-size:var(--ln-team-size);font-weight:700;letter-spacing:2px;line-height:1.2;white-space:nowrap;max-width:420px;overflow:hidden;text-overflow:ellipsis;text-shadow:0 0 10px rgba(244,114,182,.75),0 0 26px rgba(244,114,182,.35);}
.ln-team-name:empty{display:none;}
.ln-name{color:#fff;font-size:var(--ln-name-size);font-weight:800;letter-spacing:.5px;line-height:1.12;white-space:nowrap;text-shadow:0 0 12px rgba(34,211,238,.6),0 0 32px rgba(244,114,182,.28);}
.ln-sub{color:rgba(255,255,255,.78);font-size:var(--ln-sub-size);font-weight:500;line-height:1.3;margin-top:4px;white-space:nowrap;min-height:1.3em;text-shadow:0 0 10px rgba(34,211,238,.35);}
.ln-sub:empty{display:none;}
.ln-scan{position:absolute;inset:0;background:repeating-linear-gradient(180deg,rgba(255,255,255,.04) 0 1px,transparent 1px 4px);pointer-events:none;z-index:1;}
